CREATE SCHEMA IF NOT EXISTS neko;
CREATE TABLE IF NOT EXISTS neko.schema_migrations (version TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS neko.users (id TEXT PRIMARY KEY, name TEXT NOT NULL, token_hash TEXT UNIQUE NOT NULL, ai_enabled INTEGER NOT NULL DEFAULT 0, model TEXT NOT NULL DEFAULT 'xiaomi/mimo-v2.6-pro', push_token TEXT, timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata', last_sync BIGINT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, email TEXT UNIQUE, password_hash TEXT, password_salt TEXT, model_key_ciphertext TEXT);
CREATE TABLE IF NOT EXISTS neko.sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES neko.users(id), expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS neko.transactions (user_id TEXT NOT NULL REFERENCES neko.users(id), id TEXT NOT NULL, occurred_at BIGINT NOT NULL, amount_paise BIGINT NOT NULL CHECK(amount_paise>0), direction TEXT NOT NULL, category TEXT NOT NULL, merchant TEXT NOT NULL, status TEXT NOT NULL, review TEXT NOT NULL, account_alias TEXT NOT NULL, transfer_id TEXT, updated_at BIGINT NOT NULL, spending_treatment TEXT NOT NULL DEFAULT 'AUTO', related_transaction_id TEXT, principal_paise BIGINT, PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS tx_user_date ON neko.transactions(user_id,occurred_at);
CREATE TABLE IF NOT EXISTS neko.budgets (user_id TEXT NOT NULL REFERENCES neko.users(id), category TEXT NOT NULL, amount_paise BIGINT NOT NULL, PRIMARY KEY(user_id,category));
CREATE TABLE IF NOT EXISTS neko.goals (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES neko.users(id), title TEXT NOT NULL, kind TEXT NOT NULL, hour INTEGER NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, next_run BIGINT NOT NULL, last_run BIGINT, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS goals_due ON neko.goals(enabled,next_run);
CREATE TABLE IF NOT EXISTS neko.tasks (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES neko.users(id), kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, due_at BIGINT NOT NULL, lease_until BIGINT NOT NULL DEFAULT 0, result TEXT, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS tasks_due ON neko.tasks(status,due_at);
CREATE TABLE IF NOT EXISTS neko.activity (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES neko.users(id), kind TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, proposal TEXT, status TEXT NOT NULL DEFAULT 'unread', created_at BIGINT NOT NULL, push_sent INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS activity_user_date ON neko.activity(user_id,created_at);
CREATE TABLE IF NOT EXISTS neko.chat (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES neko.users(id), role TEXT NOT NULL, content TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS chat_user_date ON neko.chat(user_id,created_at);
CREATE TABLE IF NOT EXISTS neko.usage (user_id TEXT NOT NULL REFERENCES neko.users(id), day TEXT NOT NULL, month TEXT NOT NULL, requests INTEGER NOT NULL DEFAULT 0, cost DOUBLE PRECISION NOT NULL DEFAULT 0, reserved DOUBLE PRECISION NOT NULL DEFAULT 0, PRIMARY KEY(user_id,day));
CREATE TABLE IF NOT EXISTS neko.groups (id TEXT PRIMARY KEY, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES neko.users(id), invite_hash TEXT NOT NULL, invite_expires BIGINT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS neko.members (group_id TEXT NOT NULL REFERENCES neko.groups(id), user_id TEXT NOT NULL REFERENCES neko.users(id), PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS neko.expenses (id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES neko.groups(id), creator_id TEXT NOT NULL REFERENCES neko.users(id), payer_id TEXT NOT NULL REFERENCES neko.users(id), amount_paise BIGINT NOT NULL CHECK(amount_paise>0), title TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'expense', idempotency_key TEXT NOT NULL, created_at BIGINT NOT NULL, UNIQUE(creator_id,idempotency_key));
CREATE TABLE IF NOT EXISTS neko.shares (expense_id TEXT NOT NULL REFERENCES neko.expenses(id), user_id TEXT NOT NULL REFERENCES neko.users(id), amount_paise BIGINT NOT NULL CHECK(amount_paise>=0), PRIMARY KEY(expense_id,user_id));
CREATE TABLE IF NOT EXISTS neko.auth_attempts (key TEXT PRIMARY KEY, window_start BIGINT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0);
